+    private void saveNoViolationsInRepair(Properties current, String description, String existingFileName) {
+        if (existingFileName == null) {
+            return;
+        }
+        if (isShared(description, existingFileName, current)) {
+            Properties updated = copyOf(current);
+            updated.remove(description);
+            storedRules.replaceProperties(updated);
+            return;
+        }
+
+        RemovalBackup backup = prepareRemoval(existingFileName);
+        Properties updated = copyOf(current);
+        updated.remove(description);
+        try {
+            storedRules.replaceProperties(updated);
+            backup.finish();
+        } catch (RuntimeException e) {
+            backup.rollback();
+            throw e;
+        }
+    }
