+    private String requireRuleFileName(String description, boolean initialization) {
+        String fileName;
+        try {
+            fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw nameFailure(description, initialization, e);
+        }
+        if (fileName == null || fileName.isEmpty()) {
+            throw nameFailure(description, initialization, null);
+        }
+        return fileName;
+    }
+
+    private RuntimeException nameFailure(String description, boolean initialization, Throwable cause) {
+        String message = String.format("RuleViolationFileNameStrategy yielded no name for rule '%s'", description);
+        if (initialization) {
+            return cause == null ? new StoreInitializationFailedException(message) : new StoreInitializationFailedException(message, cause);
+        }
+        return cause == null ? new StoreUpdateFailedException(message) : new StoreUpdateFailedException(message, cause);
+    }
