+    private Path validateNewDestination(String fileName) {
+        Path destination = validateDirectPath(fileName, "new rule violation file");
+        if (isIndex(destination) || existsWithoutFollowingLinks(destination)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to overwrite existing store content at '%s'", fileName));
+        }
+        return destination;
+    }
