+    private Path validateDirectPath(String fileName, String what) {
+        try {
+            Path result = storeFolder.toPath().resolve(fileName).normalize();
+            if (!isDirectPath(result) || isIndex(result)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write %s '%s' outside the store folder", what, fileName));
+            }
+            return result;
+        } catch (InvalidPathException e) {
+            throw new StoreUpdateFailedException(String.format("Invalid %s '%s'", what, fileName));
+        }
+    }
