+    private void writeAtomically(Path destination, byte[] content, boolean mayReplace) {
+        if (!mayReplace && existsWithoutFollowingLinks(destination)) {
+            throw new StoreUpdateFailedException(String.format("Refusing to overwrite '%s'", destination));
+        }
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-store-", ".tmp");
+            Files.write(temporary, content);
+            moveReplacing(temporary, destination);
+            temporary = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporary != null) {
+                deleteQuietly(temporary);
+            }
+        }
+    }
