+    private IntegrityReport inspect(Properties properties) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String recordedName = properties.getProperty(description);
+            String derivedName = randomFileNames
+                    ? recordedName
+                    : requireRuleFileName(description, true);
+            Entry entry = new Entry(description, recordedName, derivedName, resolveFile(recordedName));
+            entries.add(entry);
+        }
+        entries.sort(ENTRY_ORDER);
+
+        Map<String, List<Entry>> names = new HashMap<>();
+        Map<FileIdentity, List<Entry>> files = new HashMap<>();
+        Map<String, String> derivedNames = new HashMap<>();
+        for (Entry entry : entries) {
+            names.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
+            if (entry.file.identity != null) {
+                files.computeIfAbsent(entry.file.identity, ignored -> new ArrayList<>()).add(entry);
+            }
+            if (entry.derivedName != null) {
+                derivedNames.put(entry.derivedName, entry.derivedName);
+            }
+        }
+        for (List<Entry> group : names.values()) {
+            if (group.size() > 1) {
+                group.forEach(entry -> entry.shared = true);
+            }
+        }
+        for (List<Entry> group : files.values()) {
+            if (group.size() > 1) {
+                group.forEach(entry -> entry.shared = true);
+            }
+        }
