+        Map<String, Integer> derivedCounts = new HashMap<>();
+        for (Entry entry : entries) {
+            derivedCounts.merge(entry.derivedName, 1, Integer::sum);
+        }
+        for (Entry entry : entries) {
+            entry.broken = !entry.file.valid;
+            entry.resolved = !entry.broken && fileHasNoViolations(entry.file.target);
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            entry.colliding = derivedCounts.get(entry.derivedName) > 1;
+            entry.occupied = entry.misplaced && (derivedCounts.containsKey(entry.derivedName)
+                    && derivedCounts.get(entry.derivedName) > 1
+                    || !isDirectPathQuietly(entry.derivedName)
+                    || existsWithoutFollowingLinksQuietly(entry.derivedName)
+                    || recordedByAnother(entry, entries));
+        }
