+                storedRules.createAndLoad();
+            } else {
+                storedRules.createOrLoad();
+            }
+
+            if (integrityMode != IntegrityMode.IGNORE) {
+                IntegrityReport report = inspect(storedRules.snapshot());
+                if (integrityMode == IntegrityMode.FAIL) {
+                    if (!report.isClean()) {
+                        throw integrityFailure(report);
+                    }
+                } else {
+                    repair(report);
+                }
+            }
+        }
+    }
