+    private void configureNaming(Properties properties) {
+        if (strategyWasGivenToConstructor) {
+            // getProperty intentionally also sees Properties.defaults.
+            if (properties.getProperty(FILE_NAMES_PROPERTY_NAME) != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured when a RuleViolationFileNameStrategy was supplied to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            ruleViolationFileNameStrategy = constructorStrategy;
+            randomFileNames = false;
+            return;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            ruleViolationFileNameStrategy = description -> UUID.randomUUID().toString();
+            randomFileNames = true;
+        } else if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            ruleViolationFileNameStrategy = TextFileBasedViolationStore::descriptionFileName;
+            randomFileNames = false;
+        } else {
+            ruleViolationFileNameStrategy = instantiateFileNameStrategy(configured);
+            randomFileNames = false;
+        }
+    }
+
+    private IntegrityMode parseIntegrity(String configured) {
+        if (INTEGRITY_IGNORE.equals(configured)) {
+            return IntegrityMode.IGNORE;
+        }
+        if (INTEGRITY_REPAIR.equals(configured)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(configured)) {
+            return IntegrityMode.FAIL;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid %s value '%s'; accepted values are repair, fail and ignore",
+                INTEGRITY_PROPERTY_NAME, configured));
+    }
+
+    private RuleViolationFileNameStrategy instantiateFileNameStrategy(String className) {
+        try {
+            Class<?> type = Class.forName(className);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(type)) {
+                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
+            }
+            @SuppressWarnings("unchecked")
+            Class<? extends RuleViolationFileNameStrategy> strategyType =
+                    (Class<? extends RuleViolationFileNameStrategy>) type;
+            Constructor<? extends RuleViolationFileNameStrategy> constructor = strategyType.getConstructor();
+            return constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate RuleViolationFileNameStrategy configured by %s='%s'; it must be a class with a public no-argument constructor",
+                    FILE_NAMES_PROPERTY_NAME, className), e);
+        }
+    }
+
+    private static String descriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String readablePart = matcher.find() ? matcher.group(1) : "rule";
+        return readablePart + "-" + sha256(description);
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256")
+                    .digest(value.getBytes(StandardCharsets.UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte part : digest) {
+                result.append(String.format("%02x", part & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new AssertionError(e);
+        }
+    }
+
+    private File getStoredRulesFile() {
+        return new File(storeFolder, STORED_RULES_FILE_NAME);
+    }
+
+    private FileSyncedProperties getStoredRules(File storedRulesFile) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(),
+                    path -> new FileSyncedProperties(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private IndexState inspectIndexPath(File storedRulesFile) {
+        Path folder = storeFolder.toPath();
+        Path index = storedRulesFile.toPath();
+        if (!folder.equals(index.getParent())) {
+            return IndexState.INVALID;
+        }
+        try {
+            BasicFileAttributes attributes = Files.readAttributes(index, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
+            return attributes.isRegularFile() ? IndexState.VALID : IndexState.INVALID;
+        } catch (IOException e) {
+            return Files.exists(index, LinkOption.NOFOLLOW_LINKS) ? IndexState.INVALID : IndexState.ABSENT;
+        }
+    }
