+    @Override
+    public boolean contains(ArchRule rule) {
+        checkInitialized();
+        return storedRules.containsKey(rule.getDescription());
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        checkInitialized();
+        checkNotNull(rule);
+        checkNotNull(violations);
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storedRules) {
+            Properties current = storedRules.snapshot();
+            String description = ensureUnixLineBreaks(rule.getDescription());
+            String existingFileName = current.getProperty(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                saveNoViolationsInRepair(current, description, existingFileName);
+                return;
+            }
+            if (existingFileName == null && violations.isEmpty()) {
+                // No filename is needed for an unknown rule with no violations.
+                return;
+            }
+
+            String fileName = existingFileName;
+            if (fileName == null) {
+                fileName = requireRuleFileName(description, false);
+                Path destination = validateNewDestination(fileName);
+                byte[] content = violationsContent(violations);
+                writeAtomically(destination, content, false);
+                Properties updated = copyOf(current);
+                updated.setProperty(description, ensureUnixLineBreaks(fileName));
+                try {
+                    storedRules.replaceProperties(updated);
+                } catch (RuntimeException e) {
+                    deleteQuietly(destination);
+                    throw e;
+                }
+            } else {
+                Path destination = validateExistingDestination(fileName);
+                writeAtomically(destination, violationsContent(violations), true);
+            }
+        }
+    }
+
+    private void saveNoViolationsInRepair(Properties current, String description, String existingFileName) {
+        if (existingFileName == null) {
+            return;
+        }
+        if (isShared(description, existingFileName, current)) {
+            Properties updated = copyOf(current);
+            updated.remove(description);
+            storedRules.replaceProperties(updated);
+            return;
+        }
+
+        RemovalBackup backup = prepareRemoval(existingFileName);
+        Properties updated = copyOf(current);
+        updated.remove(description);
+        try {
+            storedRules.replaceProperties(updated);
+            backup.finish();
+        } catch (RuntimeException e) {
+            backup.rollback();
+            throw e;
+        }
+    }
+
+    private String requireRuleFileName(String description, boolean initialization) {
+        String fileName;
+        try {
+            fileName = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw nameFailure(description, initialization, e);
+        }
+        if (fileName == null || fileName.isEmpty()) {
+            throw nameFailure(description, initialization, null);
+        }
+        return fileName;
+    }
+
+    private RuntimeException nameFailure(String description, boolean initialization, Throwable cause) {
+        String message = String.format("RuleViolationFileNameStrategy yielded no name for rule '%s'", description);
+        if (initialization) {
+            return cause == null ? new StoreInitializationFailedException(message) : new StoreInitializationFailedException(message, cause);
+        }
+        return cause == null ? new StoreUpdateFailedException(message) : new StoreUpdateFailedException(message, cause);
+    }
+
+    private Path validateNewDestination(String fileName) {
+        Path destination = validateDirectPath(fileName, "new rule violation file");
+        if (isIndex(destination) || existsWithoutFollowingLinks(destination)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to overwrite existing store content at '%s'", fileName));
+        }
+        return destination;
+    }
+
+    private Path validateExistingDestination(String fileName) {
+        Path lexical = validateDirectPath(fileName, "rule violation file");
+        if (isIndex(lexical)) {
+            throw new StoreUpdateFailedException("Refusing to overwrite the stored.rules index");
+        }
+        if (!existsWithoutFollowingLinks(lexical)) {
+            return lexical;
+        }
+        FileState state = resolveFile(fileName);
+        if (!state.valid) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write outside the store folder or to a non-regular file '%s'", fileName));
+        }
+        return state.target;
+    }
+
+    private Path validateDirectPath(String fileName, String what) {
+        try {
+            Path result = storeFolder.toPath().resolve(fileName).normalize();
+            if (!isDirectPath(result) || isIndex(result)) {
+                throw new StoreUpdateFailedException(String.format(
+                        "Refusing to write %s '%s' outside the store folder", what, fileName));
+            }
+            return result;
+        } catch (InvalidPathException e) {
+            throw new StoreUpdateFailedException(String.format("Invalid %s '%s'", what, fileName));
+        }
+    }
+
+    private boolean isIndex(Path path) {
+        return storeFolder.toPath().resolve(STORED_RULES_FILE_NAME).normalize().equals(path);
+    }
+
+    private byte[] violationsContent(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        return builder.toString().getBytes(StandardCharsets.UTF_8);
+    }
+
+    private void writeAtomically(Path destination, byte[] content, boolean mayReplace) {
+        if (!mayReplace && existsWithoutFollowingLinks(destination)) {
+            throw new StoreUpdateFailedException(String.format("Refusing to overwrite '%s'", destination));
+        }
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-store-", ".tmp");
+            Files.write(temporary, content);
+            moveReplacing(temporary, destination);
+            temporary = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporary != null) {
+                deleteQuietly(temporary);
+            }
+        }
+    }
+
+    private void checkInitialized() {
+        if (storedRules == null) {
+            throw new IllegalStateException("TextFileBasedViolationStore has not been initialized");
+        }
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        checkInitialized();
+        String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+        checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+        List<String> result = readLines(ruleDetailsFileName);
+        log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+        return result;
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        FileState state = resolveFile(fileName);
+        if (!state.valid) {
+            throw new StoreReadException(new IOException("Invalid rule violation file path: " + fileName));
+        }
+        try {
+            String result = new String(toByteArray(state.target.toFile()), StandardCharsets.UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private IntegrityReport inspect(Properties properties) {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String recordedName = properties.getProperty(description);
+            String derivedName = randomFileNames
+                    ? recordedName
+                    : requireRuleFileName(description, true);
+            Entry entry = new Entry(description, recordedName, derivedName, resolveFile(recordedName));
+            entries.add(entry);
+        }
+        entries.sort(ENTRY_ORDER);
+
+        Map<String, List<Entry>> names = new HashMap<>();
+        Map<FileIdentity, List<Entry>> files = new HashMap<>();
+        Map<String, String> derivedNames = new HashMap<>();
+        for (Entry entry : entries) {
+            names.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
+            if (entry.file.identity != null) {
+                files.computeIfAbsent(entry.file.identity, ignored -> new ArrayList<>()).add(entry);
+            }
+            if (entry.derivedName != null) {
+                derivedNames.put(entry.derivedName, entry.derivedName);
+            }
+        }
+        for (List<Entry> group : names.values()) {
+            if (group.size() > 1) {
+                group.forEach(entry -> entry.shared = true);
+            }
+        }
+        for (List<Entry> group : files.values()) {
+            if (group.size() > 1) {
+                group.forEach(entry -> entry.shared = true);
+            }
+        }
+
+        Map<String, Integer> derivedCounts = new HashMap<>();
+        for (Entry entry : entries) {
+            derivedCounts.merge(entry.derivedName, 1, Integer::sum);
+        }
+        for (Entry entry : entries) {
+            entry.broken = !entry.file.valid;
+            entry.resolved = !entry.broken && fileHasNoViolations(entry.file.target);
+            entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+            entry.colliding = derivedCounts.get(entry.derivedName) > 1;
+            entry.occupied = entry.misplaced && (derivedCounts.containsKey(entry.derivedName)
+                    && derivedCounts.get(entry.derivedName) > 1
+                    || !isDirectPathQuietly(entry.derivedName)
+                    || existsWithoutFollowingLinksQuietly(entry.derivedName)
+                    || recordedByAnother(entry, entries));
+        }
+
+        List<String> unownedFiles = findUnownedFiles(entries);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private boolean recordedByAnother(Entry entry, List<Entry> entries) {
+        for (Entry other : entries) {
+            if (other != entry && other.recordedName.equals(entry.derivedName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private List<String> findUnownedFiles(List<Entry> entries) {
+        Set<FileIdentity> ownedFiles = entries.stream()
+                .map(entry -> entry.file.identity)
+                .filter(identity -> identity != null)
+                .collect(java.util.stream.Collectors.toSet());
+        List<String> result = new ArrayList<>();
+        if (!Files.isDirectory(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+            return result;
+        }
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path file : files) {
+                if (file.getFileName().toString().equals(STORED_RULES_FILE_NAME)) {
+                    continue;
+                }
+                if (Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)
+                        && !ownedFiles.contains(fileIdentity(file))) {
+                    result.add(file.getFileName().toString());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        Collections.sort(result);
+        return result;
+    }
+
+    private boolean fileHasNoViolations(Path file) {
+        try {
+            String content = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
+            return content.isEmpty() || ONLY_LINE_BREAKS_PATTERN.matcher(content).matches();
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void repair(IntegrityReport report) {
+        Properties updated = storedRules.snapshot();
+        boolean changed = false;
+        for (Entry entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                updated.remove(entry.description);
+                changed = true;
+            } else if (entry.resolved) {
+                deleteResolvedFile(entry.file);
+                updated.remove(entry.description);
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveMisplacedFile(entry);
+                updated.setProperty(entry.description, ensureUnixLineBreaks(entry.derivedName));
+                changed = true;
+            }
+        }
+        if (changed) {
+            storedRules.replaceProperties(updated);
+        }
+    }
+
+    private void deleteResolvedFile(FileState file) {
+        try {
+            if (file.symbolicLink) {
+                Files.delete(file.target);
+                Files.delete(file.lexical);
+            } else {
+                Files.delete(file.lexical);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void moveMisplacedFile(Entry entry) {
+        Path destination = validateDirectPathForRepair(entry.derivedName);
+        if (existsWithoutFollowingLinks(destination)) {
+            return;
+        }
+        try {
+            if (entry.file.symbolicLink) {
+                moveReplacing(entry.file.target, destination);
+                Files.delete(entry.file.lexical);
+            } else {
+                moveReplacing(entry.file.lexical, destination);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Path validateDirectPathForRepair(String fileName) {
+        try {
+            Path path = storeFolder.toPath().resolve(fileName).normalize();
+            if (!isDirectPath(path) || isIndex(path)) {
+                return storeFolder.toPath().resolve(".archunit-invalid-destination");
+            }
+            return path;
+        } catch (InvalidPathException e) {
+            return storeFolder.toPath().resolve(".archunit-invalid-destination");
+        }
+    }
+
+    private StoreInitializationFailedException integrityFailure(IntegrityReport report) {
+        return new StoreInitializationFailedException(report.format());
+    }
+
+    private boolean isShared(String description, String fileName, Properties properties) {
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (!otherDescription.equals(description) && fileName.equals(properties.getProperty(otherDescription))) {
+                return true;
+            }
+        }
+        FileState file = resolveFile(fileName);
+        if (file.identity == null) {
+            return false;
+        }
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (otherDescription.equals(description)) {
+                continue;
+            }
+            FileState other = resolveFile(properties.getProperty(otherDescription));
+            if (file.identity.equals(other.identity)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private RemovalBackup prepareRemoval(String fileName) {
+        FileState file = resolveFile(fileName);
+        if (!existsWithoutFollowingLinks(file.lexical)) {
+            return RemovalBackup.none();
+        }
+        if (!file.valid) {
+            throw new StoreUpdateFailedException(String.format("Cannot delete rule violation file '%s' safely", fileName));
+        }
+        Path backup = null;
+        try {
+            backup = Files.createTempFile(storeFolder.toPath(), ".archunit-delete-", ".tmp");
+            Files.delete(backup);
+            if (file.symbolicLink) {
+                moveReplacing(file.target, backup);
+                Files.delete(file.lexical);
+            } else {
+                moveReplacing(file.lexical, backup);
+            }
+            return new RemovalBackup(file, backup);
+        } catch (IOException e) {
+            if (backup != null) {
+                deleteQuietly(backup);
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private FileState resolveFile(String fileName) {
+        Path lexical;
+        try {
+            lexical = storeFolder.toPath().resolve(fileName).normalize();
+        } catch (InvalidPathException e) {
+            return FileState.broken(null, null);
+        }
+        boolean exists = existsWithoutFollowingLinks(lexical);
+        boolean direct = isDirectPath(lexical);
+        if (!exists) {
+            return new FileState(lexical, lexical, false, false, identityForMissing(lexical));
+        }
+
+        boolean symbolicLink = Files.isSymbolicLink(lexical);
+        Path target;
+        try {
+            target = lexical.toRealPath();
+        } catch (IOException e) {
+            target = symbolicLink ? symbolicTarget(lexical) : lexical;
+        }
+        boolean regular = target != null && Files.isRegularFile(target, LinkOption.NOFOLLOW_LINKS);
+        boolean targetDirect = target != null && isDirectPath(target);
+        FileIdentity identity = target == null ? null : fileIdentity(target);
+        return new FileState(lexical, target, direct && regular && targetDirect,
+                symbolicLink, identity);
+    }
+
+    private Path symbolicTarget(Path link) {
+        try {
+            return link.getParent().resolve(Files.readSymbolicLink(link)).normalize();
+        } catch (IOException e) {
+            return link;
+        }
+    }
+
+    private FileIdentity identityForMissing(Path path) {
+        if (path == null) {
+            return null;
+        }
+        if (Files.isSymbolicLink(path)) {
+            return new FileIdentity("path:" + symbolicTarget(path));
+        }
+        return new FileIdentity("path:" + path);
+    }
+
+    private FileIdentity fileIdentity(Path path) {
+        try {
+            BasicFileAttributes attributes = Files.readAttributes(path, BasicFileAttributes.class);
+            Object key = attributes.fileKey();
+            return new FileIdentity(key == null ? "path:" + path.toAbsolutePath().normalize() : "key:" + key);
+        } catch (IOException e) {
+            return new FileIdentity("path:" + path.toAbsolutePath().normalize());
+        }
+    }
+
+    private boolean isDirectPath(Path path) {
+        return path != null && storeFolder.toPath().equals(path.getParent());
+    }
+
+    private boolean isDirectPathQuietly(String name) {
+        try {
+            return isDirectPath(storeFolder.toPath().resolve(name).normalize());
+        } catch (InvalidPathException e) {
+            return false;
+        }
+    }
+
+    private boolean existsWithoutFollowingLinks(Path path) {
+        return existsWithoutFollowingLinksQuietly(path);
+    }
+
+    private boolean existsWithoutFollowingLinksQuietly(String name) {
+        try {
+            return existsWithoutFollowingLinks(storeFolder.toPath().resolve(name).normalize());
+        } catch (InvalidPathException e) {
+            return false;
+        }
+    }
+
+    private boolean existsWithoutFollowingLinks(Path path) {
+        if (path == null) {
+            return false;
+        }
+        try {
+            Files.readAttributes(path, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
+            return true;
+        } catch (IOException e) {
+            return false;
+        }
+    }
+
+    private static Properties copyOf(Properties source) {
+        Properties result = new Properties();
+        result.putAll(source);
+        return result;
+    }
+
+    private static void moveReplacing(Path source, Path destination) throws IOException {
+        try {
+            Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
+        } catch (AtomicMoveNotSupportedException e) {
+            Files.move(source, destination, StandardCopyOption.REPLACE_EXISTING);
+        }
+    }
+
+    private static void deleteQuietly(Path path) {
+        if (path == null) {
+            return;
+        }
+        try {
+            Files.deleteIfExists(path);
+        } catch (IOException ignored) {
+            // Best effort rollback/temporary-file cleanup.
+        }
+    }
+
+    private enum IndexState { ABSENT, VALID, INVALID }
+
+    private enum IntegrityMode { IGNORE, REPAIR, FAIL }
+
+    private static final Comparator<Entry> ENTRY_ORDER = Comparator
+            .comparing((Entry entry) -> entry.description)
+            .thenComparing(entry -> entry.recordedName);
+
+    private final class Entry {
+        private final String description;
+        private final String recordedName;
+        private final String derivedName;
+        private final FileState file;
+        private boolean broken;
+        private boolean resolved;
+        private boolean shared;
+        private boolean misplaced;
+        private boolean colliding;
+        private boolean occupied;
+
+        private Entry(String description, String recordedName, String derivedName, FileState file) {
+            this.description = description;
+            this.recordedName = recordedName;
+            this.derivedName = derivedName;
+            this.file = file;
+        }
+    }
+
+    private static final class FileState {
+        private final Path lexical;
+        private final Path target;
